// Parse and clean the Gemini AI response
const item = $input.item;
let jsonString = '';

if (item.json.text) {
  jsonString = item.json.text;
} else if (item.json.content && item.json.content.parts) {
  jsonString = item.json.content.parts[0].text;
} else if (item.json.output) {
  jsonString = item.json.output;
} else {
  jsonString = JSON.stringify(item.json);
}

jsonString = jsonString.trim()
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```$/, '')
  .trim();

try {
  const parsed = JSON.parse(jsonString);
  // Normalize to always have is_relevant + vessels array
  if (Array.isArray(parsed)) {
    return { json: { is_relevant: true, vessels: parsed } };
  }
  if (parsed.vessel_name) {
    return { json: { is_relevant: true, vessels: [parsed] } };
  }
  if (parsed.vessels) {
    return { json: parsed };
  }
  // Old format: single vessel object without wrapper
  return { json: { is_relevant: true, vessels: [parsed] } };
} catch (error) {
  return { json: { is_relevant: false, vessels: [], error: 'JSON parse failed: ' + error.message } };
}

// Split vessels array into individual items with source=email metadata
const vessels = $input.item.json.vessels || [];

// Get sender info from the original email
const emailData = $('Get Unread Emails').item.json;
const senderName = emailData.from?.emailAddress?.name || emailData.sender?.emailAddress?.name || 'Unknown Sender';
const senderEmail = emailData.from?.emailAddress?.address || emailData.sender?.emailAddress?.address || '';
const emailSubject = emailData.subject || '';
const emailId = emailData.id || '';
const receivedTime = emailData.receivedDateTime || new Date().toISOString();

const results = [];

for (const vessel of vessels) {
  // Set source fields
  vessel.source = 'email';
  vessel.source_identifier = `email-${emailId}`;
  vessel.last_seen_at = receivedTime;
  vessel.first_seen_at = receivedTime;

  // Use sender as owner_manager if not extracted
  if (!vessel.owner_manager || vessel.owner_manager === 'Unknown') {
    vessel.owner_manager = senderName;
  }

  // Clean vessel name
  if (vessel.vessel_name && !vessel.vessel_name.toUpperCase().startsWith('MV ')) {
    vessel.vessel_name = 'MV ' + vessel.vessel_name;
  }
  if (vessel.vessel_name) {
    vessel.vessel_name = vessel.vessel_name.toUpperCase();
  }

  // Convert arrays to strings for Supabase text columns
  if (Array.isArray(vessel.last_5_cargoes)) {
    vessel.last_5_cargoes = vessel.last_5_cargoes.join(', ');
  }
  if (Array.isArray(vessel.special_features)) {
    vessel.special_features = vessel.special_features.join(', ');
  }

  // Infer region from open_port
  const port = (vessel.open_port || '').toLowerCase();
  if (['mumbai', 'kandla', 'mundra', 'goa', 'dahej', 'hazira'].some(p => port.includes(p))) {
    vessel.region = 'WCI';
  } else if (['vizag', 'kakinada', 'gangavaram', 'krishnapatnam', 'paradip', 'haldia', 'kolkata'].some(p => port.includes(p))) {
    vessel.region = 'ECI';
  } else if (['singapore', 'johor'].some(p => port.includes(p))) {
    vessel.region = 'SE Asia';
  } else if (['shanghai', 'qingdao', 'tianjin', 'ningbo', 'guangzhou'].some(p => port.includes(p))) {
    vessel.region = 'CHN';
  } else if (['busan', 'ulsan', 'incheon'].some(p => port.includes(p))) {
    vessel.region = 'KOR';
  } else if (['tokyo', 'osaka', 'nagoya', 'yokohama'].some(p => port.includes(p))) {
    vessel.region = 'JPN';
  } else if (['jebel ali', 'fujairah', 'muscat', 'jeddah', 'dammam'].some(p => port.includes(p))) {
    vessel.region = 'AG';
  } else if (['karachi', 'port qasim'].some(p => port.includes(p))) {
    vessel.region = 'AG';
  } else if (['durban', 'richards bay', 'maputo', 'dar es salaam', 'mombasa'].some(p => port.includes(p))) {
    vessel.region = 'E. Africa';
  } else if (['santos', 'paranagua', 'rio grande'].some(p => port.includes(p))) {
    vessel.region = 'ECSA';
  } else if (['rotterdam', 'amsterdam', 'antwerp', 'hamburg'].some(p => port.includes(p))) {
    vessel.region = 'EMED';
  }

  // Infer vessel_type from DWT
  if (vessel.dwt && !vessel.vessel_type) {
    const dwt = vessel.dwt;
    if (dwt < 20000) vessel.vessel_type = 'Mini Bulkers';
    else if (dwt < 40000) vessel.vessel_type = 'Handy Size';
    else if (dwt < 55000) vessel.vessel_type = 'Handymax';
    else if (dwt < 65000) vessel.vessel_type = 'Supramax';
    else if (dwt < 82000) vessel.vessel_type = 'Ultramax';
    else if (dwt < 100000) vessel.vessel_type = 'Panamax';
    else if (dwt < 120000) vessel.vessel_type = 'Kamsarmax';
    else if (dwt < 180000) vessel.vessel_type = 'Mini Cape';
    else if (dwt < 400000) vessel.vessel_type = 'Capesize';
    else vessel.vessel_type = 'VLOC';
  }

  results.push({ json: vessel });
}

return results;
